rawOutput.stdout:
/**
 * Task API Routes
 *
 * REST endpoints for task operations:
 * - GET /api/tasks - list with filters and pagination
 * - GET /api/tasks/:ref - get single task
 * - POST /api/tasks/:ref/start - start task
 * - POST /api/tasks/:ref/note - add note
